args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?director ?directorLabel (COALESCE(?d1, ?d2, ?d3) AS ?deathDate) WHERE {
  VALUES ?film { dbr:Chad_Hanna dbr:The_Avenging_Shadow }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:deathDate ?d1. }
  OPTIONAL { ?director dbp:deathDate ?d2. }
  OPTIONAL { ?director dbp:death_date ?d3. }
  ?film rdfs:label ?filmLabel FILTER(lang(?filmLabel) = 'en').
  ?director rdfs:label ?directorLabel FILTER(lang(?directorLabel) = 'en').
}

